const searchProblemsForMember = `-- name: SearchProblemsForMember :many

SELECT p.problem_id, p.title, p.source, p.submit, p.accepted, p.defunct, p.coin
FROM problem p
WHERE p.defunct = 'N'
  AND (p.title LIKE ? OR p.source LIKE ?)
  AND p.problem_id NOT IN (
    SELECT cp.problem_id
    FROM contest c
    INNER JOIN contest_problem cp ON c.contest_id = cp.contest_id
    WHERE c.defunct = 'N' AND ? < c.end_time
  )
ORDER BY p.problem_id
LIMIT ? OFFSET ?
`

type SearchProblemsForMemberParams struct {
	TitleLike  string         `json:"title_like"`
	SourceLike sql.NullString `json:"source_like"`
	Now        sql.NullTime   `json:"now"`
	Limit      int32          `json:"limit"`
	Offset     int32          `json:"offset"`
}

type SearchProblemsForMemberRow struct {
	ProblemID int32          `json:"problem_id"`
	Title     string         `json:"title"`
	Source    sql.NullString `json:"source"`
	Submit    sql.NullInt32  `json:"submit"`
	Accepted  sql.NullInt32  `json:"accepted"`
	Defunct   string         `json:"defunct"`
	Coin      uint32         `json:"coin"`
}

// 注意：下面两条查询的列必须写成 `p.xxx` 限定形式。
// sqlc 的 MySQL 分析器在"title/source 的 OR 谓词"与"含子查询"同时出现时
// 会误判 title 为歧义列（problem 与 contest_problem 都有 title 列），
// 直接写 title 会报 `column reference "title" is ambiguous`。
// 改成 NOT EXISTS 也绕不开（实测仍报），只能用表别名限定。
// 这是 sqlc 的解析缺陷，SQL 本身在 MySQL 上完全合法。
// 别图省事去掉别名限定，那样 codegen 会直接失败。
func (q *Queries) SearchProblemsForMember(ctx context.Context, arg SearchProblemsForMemberParams) ([]SearchProblemsForMemberRow, error) {
	rows, err := q.db.QueryContext(ctx, searchProblemsForMember,
		arg.TitleLike,
		arg.SourceLike,
		arg.Now,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchProblemsForMemberRow
	for rows.Next() {
		var i SearchProblemsForMemberRow
		if err := rows.Scan(
			&i.ProblemID,
			&i.Title,
			&i.Source,
			&i.Submit,
			&i.Accepted,
			&i.Defunct,
			&i.Coin,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

